class Solution:
    def nthUglyNumber(self, n, a, b, c):
        count = 0; x = 0
        while count < n:
            x += 1
            if x % a == 0 or x % b == 0 or x % c == 0:
                count += 1
        return x

solutions.better:
class Solution:
    def nthUglyNumber(self, n, a, b, c):
        import heapq
        heap=[a,b,c]; heapq.heapify(heap); seen=set(heap); val=0
        for _ in range(n):
            val=heapq.heappop(heap)
            for d in (a,b,c):
                nxt=val+d
                if nxt not in seen:
                    seen.add(nxt); heapq.heappush(heap,nxt)
        return val

