class Solution:
    def nthUglyNumber(self, n, a, b, c):
        def gcd(x,y):
            while y: x,y=y,x%y
            return x
        def lcm(x,y): return x//gcd(x,y)*y
        ab,ac,bc=lcm(a,b),lcm(a,c),lcm(b,c); abc=lcm(ab,c)
        def cnt(x):
            return x//a + x//b + x//c - x//ab - x//ac - x//bc + x//abc
        lo,hi=1,2000000000
        while lo<hi:
            mid=(lo+hi)//2
            if cnt(mid) >= n: hi=mid
            else: lo=mid+1
        return lo

